from html.parser import HTMLParser
import re, sys

class TextExtractor\(HTMLParser\):
    def __init__\(self\):
        super\(\).__init__\(\)
        self.result = []
        self.skip = False
        self.skip_tags = {'script', 'style', 'noscript', 'head'}
        self.in_pre = False
        self.in_code = False

    def handle_starttag\(self, tag, attrs\):
        if tag in self.skip_tags:
            self.skip = True
            self._skip_tag = tag
        if tag == 'pre':
            self.in_pre = True
        if tag == 'code':
            self.in_code = True
        if tag in \('br', 'p', 'div', 'tr', 'li', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'dt', 'dd'\):
            self.result.append\('\\n'\)
        if tag == 'td' or tag == 'th':
            self.result.append\(' | '\)

    def handle_endtag\(self, tag\):
        if tag in self.skip_tags and hasattr\(self, '_skip_tag'\) and self._skip_tag == tag:
            self.skip = False
        if tag == 'pre':
            self.in_pre = False
            self.result.append\('\\n'\)
        if tag == 'code':
            self.in_code = False
        if tag in \('p', 'div', 'tr', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'table', 'ul', 'ol', 'dl'\):
            self.result.append\('\\n'\)

    def handle_data\(self, data\):
        if not self.skip:
            self.result.append\(data\)

    def get_text\(self\):
        text = ''.join\(self.result\)
        # Collapse multiple blank lines
        text = re.sub\(r'\\n{3,}', '\\n\\n', text\)
        # Collapse multiple spaces \(but not newlines\)
        text = re.sub\(r'[^\\S\\n]+', ' ', text\)
        return text.strip\(\)

